flow.typescript:
// D17 · Part 0~7 · 오늘의 흐름 전체: 글자 → 음소 → id → 길이 → 스타일 → 소리 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d17_flow.ts
//   정규화 · 음소 · 사전 id · voice pack 줄 고르기 · pred_dur · 파형 · RTF까지 한 번에 (장난감 모델)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function rng(seed: number): () => number {
  // 시드를 고정하면 매번 같은 수열이 나오는 난수 (mulberry32)
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(r: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(r() + 1e-12)) * Math.cos(2 * Math.PI * r());
}

const SR_K = 24000; // Kokoro: 24 kHz
const FRAME = 600; // duration 1프레임 = 샘플 600개 (25 ms)
const VOCAB: Record<string, number> = {}; // 장난감 음소 사전
[..." .,!?'-abdefhijklmnopstuvwz" + "ɑɐɔəɛɜɪɹʃʊʌðŋʒæθʤʧ" + "ˈˌ" + "AOIWY"].forEach((c, i) => { VOCAB[c] = i + 1; });
const LEX: Record<string, string> = {
  hello: "həlˈO", world: "wˈɜɹld", kokoro: "kˈOkəɹO", makes: "mˈAks", subtitles: "sˈʌbtˌItəlz", too: "tˈu", is: "ˈɪz", a: "ɐ",
  small: "smˈɔl", text: "tˈɛkst", to: "tˌu", speech: "spˈitʃ", model: "mˈɑdəl", it: "ˈɪt", costs: "kˈɔsts", the: "ðə",
  meeting: "mˈitɪŋ", starts: "stˈɑɹts", at: "ˈæt", three: "θɹˈi", fifteen: "fˌɪftˈin", twelve: "twˈɛlv", dollars: "dˈɑləɹz",
  fifty: "fˈɪfti", cents: "sˈɛnts", and: "ænd", runs: "ɹˈʌnz", in: "ɪn", real: "ɹˈil", time: "tˈIm",
};
const UNITS_EN = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen",
  "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"];
const TENS_EN = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"];
const VOWEL_SET = new Set("aeiouAOIWYɑɐɔəɛɜɪʊʌ");

function numWords(n: number): string {
  // 0~99를 영어 낱말로: 15 -> fifteen, 50 -> fifty
  return n < 20 ? UNITS_EN[n] : TENS_EN[Math.floor(n / 10)] + (n % 10 === 0 ? "" : " " + UNITS_EN[n % 10]);
}

function normalizeEn(text: string): string {
  // 숫자 · 돈을 말로 바꾼다 (misaki의 일부 역할)
  let t = text.replace(/\$(\d+)\.(\d\d)/g, (_m, a, b) => `${numWords(+a)} dollars ${numWords(+b)} cents`);
  t = t.replace(/(\d+):(\d\d)/g, (_m, a, b) => `${numWords(+a)} ${numWords(+b)}`);
  return t.replace(/\d+/g, (m) => numWords(+m));
}

function phonemize(text: string): string {
  // 글자 -> 음소 문자열. 사전에 없는 낱말은 글자 그대로 (진짜 misaki는 규칙 + espeak 대체)
  let out = "";
  for (const tok of normalizeEn(text).match(/[A-Za-z']+|[.,!?]|\S/g) ?? []) {
    if (/[A-Za-z]/.test(tok[0])) out += (out ? " " : "") + (LEX[tok.toLowerCase()] ?? tok.toLowerCase());
    else out += tok;
  }
  return out;
}

function encode(ps: string): { ids: number[]; dropped: number } {
  // 음소 -> id. 사전에 없는 기호는 버려진다
  const ids = [...ps].filter((c) => c in VOCAB).map((c) => VOCAB[c]);
  return { ids, dropped: [...ps].length - ids.length };
}

function makePack(timbre: number, pace: number, seed: number): number[][] {
  // voice pack 흉내: 510줄 x 256. 앞 128 = 음색, 뒤 128 = 운율. 줄은 천천히 변한다
  const r = rng(seed);
  return Array.from({ length: 510 }, (_, k) =>
    Array.from({ length: 256 }, (_, j) => (j < 128 ? timbre : pace) + (0.05 * k) / 510 + 0.02 * gauss(r)));
}

const mean = (x: number[]): number => x.reduce((a, b) => a + b, 0) / x.length;

function kmodel(ps: string, refS: number[], speed = 1.0): { audio: Float32Array; predDur: number[] } {
  // KModel 흉내: 음소 -> 길이(pred_dur) -> 음높이(길이를 정한 다음) -> 파형. (신경망 대신 규칙 · 사인파)
  const chars = [...ps].filter((c) => c in VOCAB);
  const pace = 1 + 0.5 * mean(refS.slice(128)); // 운율 절반이 길이를 정한다
  const base = chars.map((c) => ("ˈˌ".includes(c) ? 1 : VOWEL_SET.has(c) ? 5 : ".,!?".includes(c) ? 6 : c === " " ? 2 : 3));
  const predDur = [2, ...base, 2].map((d) => Math.max(1, Math.round((d * pace) / speed))); // 앞뒤 경계 포함
  const frames = predDur.reduce((a, b) => a + b, 0);
  const f0Base = 180 + 60 * mean(refS.slice(0, 128)); // 음색 절반이 음높이를 정한다
  const audio = new Float32Array(frames * FRAME);
  let phase = 0;
  for (let i = 0; i < audio.length; i++) {
    const f0 = f0Base * (1.1 - (0.2 * i) / audio.length);
    phase += (2 * Math.PI * f0) / SR_K;
    audio[i] = 0.3 * Math.sin(phase);
  }
  return { audio, predDur };
}

function f0Median(y: Float32Array): number {
  // 대표 음높이(Hz): 0을 올라가며 지난 횟수로 어림
  let c = 0;
  for (let i = 1; i < y.length; i++) if (y[i - 1] < 0 && y[i] >= 0) c++;
  return c / (y.length / SR_K);
}

const text = "It costs $12.50. The meeting starts at 3:15.";
const ps = phonemize(text); // 1) 글자 -> 음소 (misaki)
const { ids, dropped } = encode(ps); // 2) 음소 -> id (모르는 기호는 버림)
const pack = makePack(0.5, 0.0, 1); // 3) voice pack에서
const refS = pack[ids.length - 1]; //    음소 수 - 1 번째 줄을 스타일로
const t0 = performance.now();
const { audio, predDur } = kmodel(ps, refS); // 4) 음소 -> 길이 -> 음높이 -> 소리
const rtf = (performance.now() - t0) / 1000 / (audio.length / SR_K);
const frames = predDur.reduce((a, b) => a + b, 0);
console.log(`${text}\n  -> ${ps}`);
console.log(`id ${ids.length}개 · 프레임 ${frames} · 소리 ${(audio.length / SR_K).toFixed(2)}초 · RTF ${rtf.toFixed(4)}`);
check(dropped === 0 && audio.length === frames * FRAME && predDur.length === ids.length + 2 && rtf < 1);

