  && normalizeEn("It costs $12.50.") === "It costs twelve dollars fifty cents."
  && phonemize("The meeting starts at 3:15.") === "ðə mˈitɪŋ stˈɑɹts ˈæt θɹˈi fˌɪftˈin." && encode("xyz").dropped === 2);

