# D17 · Part 6 · 한국어는? 음소를 직접 넣어 보기 — 단독 실행 완성 코드 (Python 3.11)
# pip install numpy==2.4.6
# 실행: python d17_korean.py   (인터넷 · GPU · 마이크 불필요 · 진짜 Kokoro 모델 다운로드 대신 장난감 모델)
#   K1(원문 그대로) vs K2(정규화 + G2P) 음소를 만들어 사전에 없어 버려지는 기호를 비교한다
import re
import numpy as np

def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")

DIGITS = "영일이삼사오육칠팔구"
ONES = ["", "한", "두", "세", "네", "다섯", "여섯", "일곱", "여덟", "아홉"]
TENS = ["", "열", "스물", "서른", "마흔", "쉰", "예순", "일흔", "여든", "아흔"]
NATIVE_COUNTERS = ["시간", "개", "명", "살", "마리", "권", "잔", "병", "장", "달", "시"]   # '시간'을 '시'보다 먼저


def sino(n: int) -> str:
    """한자어 수: 12500 -> 만이천오백"""
    if n == 0:
        return "영"
    out = ""
    for big in ["", "만", "억", "조"]:                  # 네 자리씩 끊어 읽기
        chunk, n = n % 10000, n // 10000
        s = ""
        for i, unit in enumerate(["", "십", "백", "천"]):
            d, chunk = chunk % 10, chunk // 10
            if d:
                s = ("" if d == 1 and i > 0 else DIGITS[d]) + unit + s
        if s:
            out = ("" if s == "일" and big == "만" else s) + big + out
        if n == 0:
            break
    return out


def native(n: int) -> str:
    """고유어 수: 3 -> 세, 20 -> 스무, 21 -> 스물한"""
    if not 0 < n < 100:
        return sino(n)
    return "스무" if n == 20 else TENS[n // 10] + ONES[n % 10]


def read_count(n: int, unit: str) -> str:
    return (native(n) if unit in NATIVE_COUNTERS else sino(n)) + " " + unit


def read_number(s: str) -> str:
    s = s.replace(",", "")
    if "." in s:
        a, b = s.split(".", 1)
        return sino(int(a)) + "점" + "".join(DIGITS[int(c)] for c in b)
    return sino(int(s))


def normalize_ko(text: str) -> str:
    """숫자 · 단위를 읽는 말로 바꾼다."""
    t = re.sub(r"(\d+)\s*(" + "|".join(NATIVE_COUNTERS) + ")", lambda m: read_count(int(m.group(1)), m.group(2)), text)
    t = re.sub(r"(\d[\d,]*(?:\.\d+)?)\s*%", lambda m: read_number(m.group(1)) + " 퍼센트", t)
    t = re.sub(r"\d[\d,]*(?:\.\d+)?", lambda m: read_number(m.group(0)), t)
    return re.sub(r"\s+", " ", t).strip()

CHO = list("ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ")                                   # 19
JUNG = list("ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ")                             # 21
JONG = [""] + list("ㄱㄲㄳㄴㄵㄶㄷㄹㄺㄻㄼㄽㄾㄿㅀㅁㅂㅄㅅㅆㅇㅈㅊㅋㅌㅍㅎ")               # 28 (받침 없음 포함)


def decompose(ch: str):
    """음절 -> (초성, 중성, 종성). 한글 음절이 아니면 None"""
    code = ord(ch) - 0xAC00
    if not 0 <= code < 11172:
        return None
    return CHO[code // 588], JUNG[(code % 588) // 28], JONG[code % 28]


def compose(cho: str, jung: str, jong: str = "") -> str:
    return chr(0xAC00 + (CHO.index(cho) * 21 + JUNG.index(jung)) * 28 + JONG.index(jong))

SPLIT = {"ㄳ": ("ㄱ", "ㅅ"), "ㄵ": ("ㄴ", "ㅈ"), "ㄺ": ("ㄹ", "ㄱ"), "ㄻ": ("ㄹ", "ㅁ"), "ㄼ": ("ㄹ", "ㅂ"), "ㄾ": ("ㄹ", "ㅌ"),
         "ㄿ": ("ㄹ", "ㅍ"), "ㅄ": ("ㅂ", "ㅅ")}                                            # 겹받침: 뒤 자음이 넘어감
NASAL = {"ㄱ": "ㅇ", "ㄲ": "ㅇ", "ㅋ": "ㅇ", "ㄷ": "ㄴ", "ㅅ": "ㄴ", "ㅆ": "ㄴ", "ㅈ": "ㄴ", "ㅊ": "ㄴ", "ㅌ": "ㄴ", "ㅂ": "ㅁ", "ㅍ": "ㅁ"}


def g2p_word(word: str) -> str:
    """어절 하나에 연음 · 구개음화 · 비음화 · 유음화를 적용 (g2pk2 규칙 수십 개 중 대표 4개)"""
    syl = [list(decompose(c)) if decompose(c) else c for c in word]
    for i in range(len(syl) - 1):
        a, b = syl[i], syl[i + 1]
        if not (isinstance(a, list) and isinstance(b, list)) or not a[2]:
            continue
        if b[0] == "ㅇ" and a[2] not in ("ㅇ", "ㅎ"):
            if b[1] == "ㅣ" and a[2] in ("ㄷ", "ㅌ"):          # 구개음화: 같이 -> 가치
                a[2], b[0] = "", {"ㄷ": "ㅈ", "ㅌ": "ㅊ"}[a[2]]
            else:                                               # 연음: 밥을 -> 바블
                keep, move = SPLIT.get(a[2], ("", a[2]))
                a[2], b[0] = keep, move
        elif b[0] in ("ㄴ", "ㅁ") and a[2] in NASAL:            # 비음화: 국물 -> 궁물, 합니다 -> 함니다
            a[2] = NASAL[a[2]]
        elif b[0] == "ㄹ" and a[2] == "ㄴ":                     # 유음화: 신라 -> 실라
            a[2] = "ㄹ"
    return "".join(compose(*s) if isinstance(s, list) else s for s in syl)


def g2p(text: str) -> str:
    return " ".join(g2p_word(w) for w in text.split(" "))

SR_K, FRAME = 24000, 600        # Kokoro: 24 kHz · duration 1프레임 = 샘플 600개 (25 ms)
VOCAB = {c: i for i, c in enumerate(" .,!?'-abdefhijklmnopstuvwz" + "ɑɐɔəɛɜɪɹʃʊʌðŋʒæθʤʧ" + "ˈˌ" + "AOIWY", start=1)}   # 장난감 음소 사전
LEX = {"hello": "həlˈO", "world": "wˈɜɹld", "kokoro": "kˈOkəɹO", "makes": "mˈAks", "subtitles": "sˈʌbtˌItəlz",
       "too": "tˈu", "is": "ˈɪz", "a": "ɐ", "small": "smˈɔl", "text": "tˈɛkst", "to": "tˌu", "speech": "spˈitʃ",
       "model": "mˈɑdəl", "it": "ˈɪt", "costs": "kˈɔsts", "the": "ðə", "meeting": "mˈitɪŋ", "starts": "stˈɑɹts",
       "at": "ˈæt", "three": "θɹˈi", "fifteen": "fˌɪftˈin", "twelve": "twˈɛlv", "dollars": "dˈɑləɹz", "fifty": "fˈɪfti",
       "cents": "sˈɛnts", "and": "ænd", "runs": "ɹˈʌnz", "in": "ɪn", "real": "ɹˈil", "time": "tˈIm"}
UNITS_EN = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen",
         "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
TENS_EN = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
VOWEL_SET = set("aeiouAOIWYɑɐɔəɛɜɪʊʌ")


def num_words(n: int) -> str:
    """0~99를 영어 낱말로: 15 -> fifteen, 50 -> fifty"""
    return UNITS_EN[n] if n < 20 else TENS_EN[n // 10] + ("" if n % 10 == 0 else " " + UNITS_EN[n % 10])


def normalize_en(text: str) -> str:
    """숫자 · 돈을 말로 바꾼다 (misaki의 일부 역할)"""
    text = re.sub(r"\$(\d+)\.(\d\d)", lambda m: f"{num_words(int(m.group(1)))} dollars {num_words(int(m.group(2)))} cents", text)
    text = re.sub(r"(\d+):(\d\d)", lambda m: f"{num_words(int(m.group(1)))} {num_words(int(m.group(2)))}", text)
    return re.sub(r"\d+", lambda m: num_words(int(m.group(0))), text)


def phonemize(text: str) -> str:
    """글자 -> 음소 문자열. 사전에 없는 낱말은 글자 그대로 (진짜 misaki는 규칙 + espeak 대체)"""
    out = ""
    for tok in re.findall(r"[A-Za-z']+|[.,!?]|\S", normalize_en(text)):
        if tok[0].isalpha():
            out += (" " if out else "") + LEX.get(tok.lower(), tok.lower())
        else:
            out += tok
    return out


def encode(ps: str):
    """음소 -> id. 사전에 없는 기호는 버려진다"""
    ids = [VOCAB[c] for c in ps if c in VOCAB]
    return ids, len(ps) - len(ids)


def make_pack(timbre: float, pace: float, seed: int) -> np.ndarray:
    """voice pack 흉내: (510, 1, 256). 앞 128 = 음색, 뒤 128 = 운율. 줄은 천천히 변한다"""
    rng = np.random.default_rng(seed)
    base = np.concatenate([np.full(128, timbre), np.full(128, pace)])
    return np.stack([(base + 0.05 * k / 510 + 0.02 * rng.standard_normal(256))[None, :] for k in range(510)])


def kmodel(ps: str, ref_s: np.ndarray, speed: float = 1.0):
    """KModel 흉내: 음소 -> 길이(pred_dur) -> 음높이(길이를 정한 다음) -> 파형. (신경망 대신 규칙 · 사인파)"""
    ids, _ = encode(ps)
    chars = [c for c in ps if c in VOCAB]
    pace = 1 + 0.5 * float(ref_s[0, 128:].mean())                     # 운율 절반이 길이를 정한다
    base = [1 if c in "ˈˌ" else 5 if c in VOWEL_SET else 6 if c in ".,!?" else 2 if c == " " else 3 for c in chars]
    pred_dur = np.maximum(1, np.round(np.array([2] + base + [2]) * pace / speed)).astype(int)   # 앞뒤 경계 포함
    f0 = (180 + 60 * float(ref_s[0, :128].mean())) * np.linspace(1.1, 0.9, int(pred_dur.sum()))  # 음색 절반이 음높이를 정한다
    f0 = np.repeat(f0, FRAME)
    audio = (0.3 * np.sin(2 * np.pi * np.cumsum(f0) / SR_K)).astype(np.float32)
    return audio, pred_dur


def f0_median(y: np.ndarray) -> float:
    """대표 음높이(Hz): 0을 올라가며 지난 횟수로 어림"""
    return float(((y[:-1] < 0) & (y[1:] >= 0)).sum() / (len(y) / SR_K))

CON_IPA = {"ㄱ": "k", "ㄲ": "kk", "ㄴ": "n", "ㄷ": "t", "ㄸ": "tt", "ㄹ": "ɾ", "ㅁ": "m", "ㅂ": "p", "ㅃ": "pp", "ㅅ": "s", "ㅆ": "ss",
           "ㅇ": "", "ㅈ": "ʤ", "ㅉ": "ʤʤ", "ㅊ": "ʧ", "ㅋ": "kk", "ㅌ": "tt", "ㅍ": "pp", "ㅎ": "h"}
VOW_IPA = {"ㅏ": "a", "ㅐ": "ɛ", "ㅑ": "ja", "ㅒ": "jɛ", "ㅓ": "ʌ", "ㅔ": "e", "ㅕ": "jʌ", "ㅖ": "je", "ㅗ": "o", "ㅘ": "wa", "ㅙ": "wɛ",
           "ㅚ": "we", "ㅛ": "jo", "ㅜ": "u", "ㅝ": "wʌ", "ㅞ": "we", "ㅟ": "wi", "ㅠ": "ju", "ㅡ": "ɯ", "ㅢ": "ɯi", "ㅣ": "i"}
JONG_IPA = {"ㄱ": "k", "ㄴ": "n", "ㄷ": "t", "ㄹ": "l", "ㅁ": "m", "ㅂ": "p", "ㅇ": "ŋ"}


def ko_ipa(text: str) -> str:
    """한글 -> 음소 (espeak-ng 한국어 규칙 흉내: 자모 표 조회). 한글이 아닌 글자는 그대로"""
    out = []
    for c in text:
        d = decompose(c)
        out.append(CON_IPA[d[0]] + VOW_IPA[d[1]] + (JONG_IPA.get(d[2], "t") if d[2] else "") if d else c)
    return "".join(out)


KO_SENTS = ["같이 밥을 먹으러 갈까요", "국물이 정말 맛있네요", "회의는 오후 3시에 시작합니다", "가격은 12,500원입니다"]


def ko_phonemes(text: str, mode: str):
    src = text if mode == "K1" else g2p(normalize_ko(text))
    ps = ko_ipa(src)
    return ps, sorted(set(ps) - set(VOCAB) - {" "})        # 사전에 없는 기호는 모델이 버린다


for s in KO_SENTS:
